import { describe, it } from "vitest";

describe("MHPCO claim office: quote", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword for a newcomer -> 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("plain amulet for a newcomer -> 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("plain staff for a newcomer -> 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("plain potion for a newcomer -> 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("2 runes -> base 50 G -> 60 G (50 + 5 first insurance + 5 fee)");
  it.todo("3 runes -> block base 60 G -> 71 G (60 + 6 + 5)");
  it.todo("3 moonstones -> block base 60 G -> 71 G (moonstones form blocks too)");
  it.todo("4 runes -> base 100 G (no block, block requires exactly 3) -> 115 G");
  it.todo("7 runes -> base 175 G -> 197.5 rounded up to 198 G (rounding in MHPCO's favor)");
  it.todo("2 runes + 1 moonstone -> base 75 G (alike = same type, no block) -> 88 G (87.5 rounded up)");
  it.todo("3 runes + 3 moonstones -> base 120 G (two separate blocks) -> 137 G");
  it.todo("cursed sword for a newcomer -> 165 G (100 + 50 curse + 10 first insurance + 5 fee)");
  it.todo("sword enchantment 5 -> 145 G (100 + 30 high enchantment + 10 + 5)");
  it.todo("cursed sword enchantment 5 -> 195 G (both surcharges apply: 100 + 50 + 30 + 10 + 5)");
  it.todo("sword enchantment 4 -> 115 G (no high-enchantment surcharge)");
  it.todo("cursed sword enchantment 4 -> 165 G (curse only)");
  it.todo("cursed sword + plain amulet -> 231 G (curse surcharge on the sword's 100 only: 160 + 50 + 16 + 5)");
  it.todo("customer with exactly 2 years, plain sword -> 95 G (100 - 20 loyalty + 10 + 5)");
  it.todo("customer with 1 year, plain sword -> 115 G (no loyalty discount)");
  it.todo("customer with 2 years, sword + amulet -> 149 G (loyalty on the policy base 160: 160 - 32 + 16 + 5)");
  it.todo("second quote of a newcomer, plain sword -> 100 G (100 + 10 first - 15 follow-up + 5)");
  it.todo("third quote also receives the follow-up discount -> 100 G");
  it.todo("long-standing customer's second quote, cursed sword enchantment 7 -> 160 G (integration example)");
  it.todo("schema example: amulet for 5 years customer -> 59 G (60 - 12 + 6 + 5)");
  it.todo("quote with unknown item type 'broomstick' is rejected with an error and writes no results");
});

describe("MHPCO claim office: claim", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 -> payout 400, remaining cap 1600");
  it.todo("damage to a rune, damage 200 -> payout 100 (no special clause)");
  it.todo("damage of 100 or less -> payout 0 (deductible fully consumes the damage)");
  it.todo("steel sword enchantment 8, damage 1000 -> payout 400 (high-enchantment clause at the threshold)");
  it.todo("steel sword enchantment 7, damage 1000 -> payout 900 (below the threshold)");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400 (50 % first, then deductible)");
  it.todo("dragon-material sword enchantment 8, damage 1000 -> payout 400");
  it.todo("dragon-material sword enchantment 9, damage 1000 -> payout 400 (50 % rule wins)");
  it.todo("dragon-material sword enchantment 5, damage 800 -> payout 700 (full reimbursement then deductible)");
  it.todo("dragon attack damages sword (500) and amulet (300) -> payout 600 (deductible per damaged item)");
  it.todo("policy with two swords: insurance sum 2000, cap 4000 -> remaining cap after claim reflects 4000");
  it.todo("two sword damages on two insured swords -> each with its own deductible (payout 800 for 500 + 500)");
  it.todo("each damage entry applies to the matching insured item's enchantment (two swords, enchantment 9 and 3)");
  it.todo("more sword damages than insured swords -> claim rejected with an error");
  it.todo("sword + amulet policy -> cap 3200 (remaining cap after a 500 sword damage is 2800)");
  it.todo("amulet-only policy -> cap 1200 (insurance value 600)");
  it.todo("staff-only policy -> cap 1600 (insurance value 800)");
  it.todo("potion-only policy -> cap 800 (insurance value 400)");
  it.todo("moonstone-only policy -> cap 500 (insurance value 250)");
  it.todo("cursed sword -> cap 2000 (premium modifiers do not raise the cap)");
  it.todo("sword + 3 runes -> insurance sum 1750, cap 3500 (block discount does not affect the sum)");
  it.todo("two successive claims of 1500 on a sword -> payout 1400 / cap 600, then payout 600 / cap 0");
  it.todo("caps of different policies are tracked independently");
  it.todo("payout calculation yielding 350.5 -> 350 (rounded down)");
  it.todo("damage to an amulet not part of a sword-only policy -> claim rejected with an error");
  it.todo("damage with unknown item type -> claim rejected with an error");
  it.todo("damage with amount -200 -> claim rejected with an error");
  it.todo("claim referencing a step that is not a quote -> claim rejected with an error (chosen reading)");
  it.todo("schema example: amulet policy, fire, damage 200 -> payout 100, remaining cap 1100");
});

