1	export interface QuoteResult {
2	  premium: number;
3	}
4	
5	export interface ClaimResult {
6	  payout: number;
7	  remainingCap: number;
8	}
9	
10	export interface ScenarioResult {
11	  results: Array<QuoteResult | ClaimResult>;
12	}
13	
14	export interface Item {
15	  type: string;
16	  material?: string;
17	  enchantment?: number;
18	  cursed?: boolean;
19	}
20	
21	export interface QuoteStep {
22	  op: "quote";
23	  items: Item[];
24	}
25	
26	export interface Scenario {
27	  customer: { yearsWithMHPCO: number };
28	  steps: QuoteStep[];
29	}
30	
31	const PROCESSING_FEE = 5;
32	const PERCENT = 100;
33	const FIRST_INSURANCE_PERCENT = 10;
34	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
35	const LOYALTY_THRESHOLD_YEARS = 2;
36	const LOYALTY_DISCOUNT_PERCENT = 20;
37	const CURSE_SURCHARGE_PERCENT = 50;
38	const HIGH_ENCHANTMENT_THRESHOLD = 5;
39	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
40	
41	const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40 };
42	const COMPONENT_BASE_PREMIUM = 25;
43	const COMPONENT_BLOCK_SIZE = 3;
44	const COMPONENT_BLOCK_PREMIUM = 60;
45	
46	const COMPONENT_TYPES = ["rune", "moonstone"];
47	
48	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
49	
50	const alikeComponentsPremium = (count: number): number =>
51	  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : count * COMPONENT_BASE_PREMIUM;
52	
53	const componentsPremium = (components: Item[]): number =>
54	  COMPONENT_TYPES.reduce(
55	    (sum, type) => sum + alikeComponentsPremium(components.filter((component) => component.type === type).length),
56	    0,
57	  );
58	
59	const curseSurchargePercent = (item: Item): number => (item.cursed ? CURSE_SURCHARGE_PERCENT : 0);
60	
61	const highEnchantmentSurchargePercent = (item: Item): number =>
62	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
63	
64	const itemSurchargePercent = (item: Item): number => curseSurchargePercent(item) + highEnchantmentSurchargePercent(item);
65	
66	const mainItemBasePremium = (item: Item): number => {
67	  const premium = BASE_PREMIUMS[item.type];
68	  if (premium === undefined) {
69	    throw new Error(`Unknown item type: ${item.type}`);
70	  }
71	  return premium;
72	};
73	
74	const itemBasePremium = (item: Item): number =>
75	  isComponent(item) ? COMPONENT_BASE_PREMIUM : mainItemBasePremium(item);
76	
77	const itemSurchargeOf = (item: Item): number => (itemBasePremium(item) * itemSurchargePercent(item)) / PERCENT;
78	
79	const basePremiumOf = (items: Item[]): number => {
80	  const mainItems = items.filter((item) => !isComponent(item));
81	  const components = items.filter(isComponent);
82	  return mainItems.reduce((sum, item) => sum + mainItemBasePremium(item), 0) + componentsPremium(components);
83	};
84	
85	const loyaltyDiscountPercent = (yearsWithMHPCO: number): number =>
86	  yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_PERCENT : 0;
87	
88	const followUpDiscountPercent = (isFollowUpContract: boolean): number =>
89	  isFollowUpContract ? FOLLOW_UP_DISCOUNT_PERCENT : 0;
90	
91	const policyWidePercent = (yearsWithMHPCO: number, isFollowUpContract: boolean): number =>
92	  PERCENT +
93	  FIRST_INSURANCE_PERCENT -
94	  loyaltyDiscountPercent(yearsWithMHPCO) -
95	  followUpDiscountPercent(isFollowUpContract);
96	
97	const quotePremium = (items: Item[], yearsWithMHPCO: number, isFollowUpContract: boolean): number => {
98	  const base = basePremiumOf(items);
99	  const itemSurcharges = items.reduce((sum, item) => sum + itemSurchargeOf(item), 0);
100	  const total = base * policyWidePercent(yearsWithMHPCO, isFollowUpContract) + itemSurcharges * PERCENT;
101	  return Math.ceil(total / PERCENT) + PROCESSING_FEE;
102	};
